	spec := upSpec()
	spec.Devices = []string{"d1"}
	spec.BatchSize = 1
	createCampaign(t, s, spec)
	bringOnline(t, s, "d1")

	_, failAt := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
	v, _ := s.GetCampaign(spec.ID)

